grok.matchRules:
activemq %{_date_old}\s+\|\s+%{_level}\s+\|\s+%{data:msg}\s+\| %{_logger_name}\s+\|\s+%{_thread_name}
artemis %{_date_old}\s+%{_level}\s+\[%{_logger_name}\]\s+(%{_message_id}: )?%{data:msg}
artemis_audit_general %{_date_old}\s+\[%{_type}\]%{_thread_logger}\s+%{_message_id}\: %{data:msg}
audit_requested_new %{_level}\s+\|\s+%{_username} requested %{_action_url} \[%{_action_params}\] from\s+%{_action_from} at %{_date_new}\s+\|\s+.*
audit_requested_old %{_date_old}\s+\|\s+%{_level}\s+\|\s+%{_username} requested %{_action_url} \[%{_action_params}\] from\s+%{_action_from}\s+\|\s+.*
audit_called_old %{_date_old}\s+\|\s+%{_level}\s+\|\s+%{_username} called %{notSpace:system.action}\[%{data:system.properties}\]\s+\|.*-%{_action_from}
audit_catch_all_new %{_level}\s+\|\s+%{_username}.*from\s+%{_action_from} at %{_date_new}.*
audit_catch_all_old %{_date_old}\s+\|\s+%{_level}\s+\|\s+%{_username}.*-%{_action_from}

grok.supportRules:
_date_legacy %{date("yyyy-MM-dd HH:mm:ss,SSS"):timestamp}
_date_iso_offset %{date("yyyy-MM-dd'T'HH:mm:ss.SSSZ"):timestamp}
_date_iso_zulu %{date("yyyy-MM-dd'T'HH:mm:ss.SSS'Z'"):timestamp}
_date (%{_date_iso_offset}|%{_date_iso_zulu}|%{_date_legacy})
_date_any (%{date("yyyy-MM-dd'T'HH:mm:ss.SSSZ")}|%{date("yyyy-MM-dd'T'HH:mm:ss.SSS'Z'")}|%{date("yyyy-MM-dd HH:mm:ss,SSS")})
_file %{notSpace:filename}:%{integer:lineno}
_base_prefix \[%{_date}\]\s+(\{\{%{_file}\}\}|\{%{_file}\})\s+%{word:level}\s+-
# Some logs have duplicate prefixes, we only collect job_id and subtask name from first prefix if present.
_prefix (\[%{_date_any}\]\s+(\{\{%{notSpace}:%{integer}\}\}|\{%{notSpace}:%{integer}\})\s+%{word}\s+-\s+)?(Job %{integer:jobid}: Subtask %{word:subtask}\s+)?%{_base_prefix}

grok.matchRules:
airflow_stacktrace %{_prefix}\s+%{data:message}\nTraceback \(most recent call last\):\n%{data:error.stack}

airflow_env_vars %{_prefix}\s+Exporting the following env vars:(\n%{data:env_vars:keyvalue("=", ":+")})?

airflow_default %{_prefix}\s+%{data:message}

alerts %{_timestamp} \[%{_level}\] \[%{notSpace}\] \[%{word:ambari.service:lowercase}\] \[%{word:component}\] %{data}
audit %{_timestamp_2}, User\(%{word:usr.name}\), RemoteIp\(%{notSpace:network.client.ip}\), Operation\(%{data:system.operation}\), Roles\(%{data:roles}\), Status\(%{word:status}\)(, Reason\(%{data:error.message}\))?(, Consecutive failures\(%{data:error.consecutive_failures}\))?
config %{_timestamp}  %{_level} - \(configchange\)\s+type: '%{notSpace:type}', tag: '%{notSpace:tag}', version: '%{notSpace:version}'
config_message %{_timestamp}  %{_level} - \(configchange\)\s+%{data}
server %{_timestamp}  %{_level} \[%{notSpace:logger.thread_name}\] %{_logger_name} - %{data}
server.command %{_level} %{_timestamp} %{_logger_name} - %{data}
server.check.database %{_timestamp}\s+%{_level} - %{data}

kubernetes_general %{regex("\\w"):level}%{date("MMdd HH:mm:ss.SSSSSS"):timestamp}\s+%{number:logger.thread_id} %{_logger}\] %{_msg}
redis redis\: %{date("yyyy/MM/dd HH:mm:ss"):timestamp}\s+%{_logger}\:\s+%{_msg}
tracing_log Trace\[%{word:argocd_trace_id}\W+%{regex("([a-zA-Z ]+)"):action}\W+%{_level}:%{_msg}
argocd_stats time="%{_date}" level=%{_level} msg="%{_stats}"
argocd_common time="%{_date}" level=%{_level} %{regex("(?<msg>.*)")::keyvalue}

edge_hub_http_start %{_prefix}%{_timestamp} \[%{_level}\] - Request starting %{_http_version} %{_http_method} %{_http_url}
edge_hub_http_end %{_prefix}%{_timestamp} \[%{_level}\] - Request finished in %{_duration}ms %{_http_status_code} %{_http_content_type}; %{_http_fields}
device_http %{_prefix}%{_device_timestamp} \[%{_level}\] - \[%{_loggerName}\] - - - \[%{_device_http_timestamp}\] "%{_http_method} %{_http_url} %{_http_version}" %{_http_status_code} %{_http_reason_phrase} %{_http_bytes_written} "%{_http_ident}" "%{_http_auth}" auth_id\(%{_http_auth_id}\)
device_default %{_prefix}%{_device_timestamp} \[%{_level}\] - %{data:msg}
default %{_prefix}%{_timestamp} \[%{_level}\] - %{data:msg}

dnsDead firewall:\s+\[%{word:secure_edge.firewall.service}\]\s+Operation:\s+DNS server with IP %{ip:secure_edge.firewall.dns.dead_server} now considered dead%{data}
dnsDeadWithTypo firewall:\s+\[%{word:secure_edge.firewall.service}\]\s+Operation:\s+DNS server with IP %{ip:secure_edge.firewall.dns.dead_server} now considererd dead%{data}
dnsRecoverd firewall:\s+\[%{word:secure_edge.firewall.service}\]\s+Operation:\s+DNS server with IP %{ip:secure_edge.firewall.dns.recovered_server} now considered healthy%{data}
dnsRecoveredWithTypo firewall:\s+\[%{word:secure_edge.firewall.service}\]\s+Operation:\s+DNS server with IP %{ip:secure_edge.firewall.dns.recovered_server} now considererd healthy%{data}
unhealthyServer firewall:\s+\[%{word:secure_edge.firewall.service}\]\s+Operation:\s+DNS server with IP %{ip:secure_edge.firewall.dns.unhealthy_server} did not respond to health check%{data}
autoFilledRule1 firewall:\s+\[%{word:secure_edge.firewall.service}\]\s+%{word:secure_edge.firewall.operation}:\s+%{data:secure_edge.firewall.operation_details}

loginAttempt LOGIN ATTEMPT:\s+%{data}: Login \(%{data:secure_edge.ssh.login.type}\) %{data:secure_edge.ssh.login.user} from %{ip:secure_edge.ssh.login.from} port %{port:secure_edge.ssh.login.port} %{data:secure_edge.ssh.login.result}
signalReceived sshd:\s+Received signal %{number:secure_edge.ssh.signal.value}; %{data:secure_edge.ssh.signal.action}
serverListening sshd:\s+Server listening on %{ip:secure_edge.ssh.ip} port %{port:secure_edge.ssh.port}(.)?
connectionClosed sshd:\s+Connection closed by %{ip:secure_edge.ssh.connection.close.ip} port %{port:secure_edge.ssh.connection.close.port}
connectionStarted sshd:\s+Connection from %{ip:secure_edge.ssh.connection.open.from_ip} port %{port:secure_edge.ssh.connection.open.from_port} on %{ip:secure_edge.ssh.connection.open.to_ip} port %{port:secure_edge.ssh.connection.open.to_port}
shellOpened sshd:%{data}Shell \(%{data:secure_edge.ssh.shell.process}\) opened for user %{data:secure_edge.ssh.shell.user}@%{ip:secure_edge.ssh.shell.ip}:%{port:secure_edge.ssh.shell.port}%{data}

openSocket Opened listen socket on %{ip:secure_edge.access.open_socket.ip}:%{port:secure_edge.access.open_socket.port}
closeSocket Shut down listen socket on %{ip:secure_edge.access.close_socket.ip}:%{port:secure_edge.access.close_socket.port}
connectedHandler Connected new handler #%{number:secure_edge.access.handler.id} of type '%{word:secure_edge.access.handler.type}'
socketConnectError Handler #%{number:secure_edge.access.handler.id} returned with code %{number:secure_edge.access.handler.return_code} \(IOStreamSock: Connect\(%{ip:secure_edge.access.handler.socket.ip}:%{port:secure_edge.access.handler.socket.port}\): %{data:secure_edge.access.handler.error_message}\)
handlerReturned Handler #%{number:secure_edge.access.handler.id} returned with code %{number:secure_edge.access.handler.return_code} \(%{data:secure_edge.access.handler.return_message}\)
boxGroupType Box group type: %{data:secure_edge.access.group}

autoFilledRule1 \[%{data:secure_edge.admin.config.commit.user}@%{ip:secure_edge.admin.config.commit.ip}_%{port:secure_edge.admin.config.commit.port}\]\s+%{commitData}
autoFilledRule2 \[%{data:secure_edge.admin.config.commit.process}\]\s+%{commitData}
commitStartUser \[%{data:secure_edge.admin.config.commit.user}@%{ip:secure_edge.admin.config.commit.ip}_%{port:secure_edge.admin.config.commit.port}\]\s+Commit Start
commitStartProcess \[%{data:secure_edge.admin.config.commit.process}\]\s+Commit Start

rule_1 %{regex(".*(?=/)"):managed_system}/%{regex(".*(?=,)"):managed_account}, %{data}

rule_2 ManagedSystem for %{regex("DB Server"):managed_system_type} Instance: Asset=%{regex(".*(?= InstanceName=)"):managed_system} InstanceName=%{data:instance_name}

rule_3 Asset:%{regex(".*(?= \\(Db Instance)"):managed_system} \(Db Instance: %{regex(".*(?=, Port:)"):db_instance}, Port:(%{notSpace:port}\) MAccount|%{notSpace:port}\) Account):%{data:managed_account}

rule_4 %{regex("Asset|Cloud|Domain"):managed_system_type}:(%{regex(".*(?= MAccount:)"):managed_system} MAccount|%{regex(".*(?= Account:)"):managed_system} Account):%{data:managed_account}

rule_5 ManagedSystem for %{regex("Asset|Cloud|Domain"):managed_system_type}=%{data:managed_system}

rule_6 ManagedSystem=%{regex(".*(?= ManagedAccount=)"):managed_system} ManagedAccount=%{data:managed_account}

rule_7 FAccount=%{regex("(.*(?= FAlias=))"):functional_account} FAlias=%{regex("(.*(?= FDomain=))"):functional_alias} FDomain=%{notSpace:functional_domain} PFid=%{data:pfid}

parse_network_log1 %{regex("listening"):vendor_action} on %{notSpace:proto} interface %{notSpace:interface}, %{ipv4:network.client.ip}\#%{port:network.client.port}
parse_network_log2 %{regex("no longer listening"):vendor_action} on %{ipv4:network.client.ip}\#%{port:network.client.port}
parse_network_log3 %{regex("not listening"):vendor_action} on any interfaces

parse_notify_log_1 %{extract_dns_domain_class_and_action} \(serial %{number:serial_number}\)
parse_notify_log_2 %{extract_dns_domain_class_and_action} to %{ipv4:network.destination.ip}\#%{port:network.destination.port}(( failed: |: )%{greedyData:failure_reason})?
parse_notify_log_3 %{extract_dns_domain_class_and_action} from %{ipv4:network.client.ip}\#%{port:network.client.port}: %{word:dns.flags.rcode}

